    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);
        c.addToBalance{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint contractBefore = address(c).balance;
        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && balBefore == depositAmount && address(c).balance == contractBefore - balBefore);
    }
    receive() external payable {}
}

